int platform_execute_task(const char* task) {
    if (!task) {
        return -1;
    }

    printf("[LINUX] Executing task: %s\n", task);

    int ret = system(task);

    if (ret == -1) {
        printf("[LINUX] Task execution failed\n");
        return -1;
    }

    printf("[LINUX] Task completed with exit code: %d\n", ret);
    return ret;
